SELECT COUNT(DISTINCT customer_unique_id) AS customer_count
FROM customers
WHERE customer_unique_id IS NOT NULL;

SELECT COUNT(*) AS cnt
FROM order_payments
WHERE payment_type = 'credit_card';

SELECT COUNT(*) AS product_cnt
FROM products
WHERE product_weight_g > 5000;

SELECT COUNT(*) AS undelivered_order_cnt
FROM orders
WHERE order_delivered_customer_date IS NULL;

SELECT COUNT(*) AS review_count
FROM order_reviews
WHERE TRIM(review_comment_title) <> '';

SELECT COUNT(*) AS detail_count
FROM order_items
WHERE price < 10;

SELECT COUNT(*) AS ticket_count
FROM support_tickets
WHERE priority = '4';

SELECT COUNT(*) AS record_count
FROM inventory
WHERE quantity < safety_stock;

SELECT COUNT(*) AS ended_campaign_count
FROM campaigns
WHERE status = 3;

SELECT COUNT(*) FILTER (WHERE payment_type = 'credit_card') AS credit_card_cnt,
       COUNT(*) FILTER (WHERE payment_type = 'boleto') AS boleto_cnt
FROM order_payments;

SELECT ROUND(SUM(refund_amount), 2) AS total_refund_amount
FROM refunds
WHERE status = 4;

