SELECT ROUND(MAX(price), 2) AS max_price,
       ROUND(MIN(price), 2) AS min_price
FROM order_items;

SELECT ROUND(AVG(EXTRACT(EPOCH FROM (order_delivered_customer_date - order_purchase_timestamp))::numeric / 86400), 2) AS avg_days
FROM orders
WHERE order_delivered_customer_date IS NOT NULL AND order_purchase_timestamp IS NOT NULL;

SELECT COUNT(*) AS late_order_count
FROM orders
WHERE order_delivered_customer_date > order_estimated_delivery_date;

SELECT ROUND(COUNT(*) FILTER (
    WHERE order_delivered_customer_date IS NOT NULL
      AND order_delivered_customer_date > order_estimated_delivery_date
)::numeric / NULLIF(COUNT(*) FILTER (
    WHERE order_delivered_customer_date IS NOT NULL
), 0), 4) AS late_delivery_rate
FROM orders;

SELECT ROUND(AVG(EXTRACT(EPOCH FROM (resolved_at - created_at)) / 3600.0)::numeric, 2) AS avg_resolution_hours
FROM support_tickets
WHERE resolved_at IS NOT NULL;

SELECT ROUND(
         COUNT(DISTINCT r.order_id)::numeric / NULLIF(COUNT(DISTINCT o.order_id), 0)::numeric,
         4
       ) AS refund_order_ratio
FROM orders o
LEFT JOIN refunds r ON r.order_id = o.order_id;
